<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<script src="https://drive.baibai.cv/f/ZKEBuW/Music.js"></script>
<style>
/* ───────── 星空主题（清晰版，无毛玻璃）──────── */
@keyframes twinkle {
  0%, 100% { opacity: 0.28; transform: scale(1); }
  50%      { opacity: 1;   transform: scale(1.2); }
}
@keyframes twinkleSoft {
  0%, 100% { opacity: 0.4; text-shadow: 0 0 0px currentColor; }
  50%      { opacity: 1;   text-shadow: 0 0 2px currentColor; }
}
@keyframes vinylSpin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
@keyframes equalizeWave {
  0%, 100% { height: 4px; }
  50%      { height: 12px; }
}
@keyframes choiceFlyIn {
  to { opacity: 1; transform: translateY(0); }
}
* { box-sizing: border-box; }
body {
  margin: 0;
  padding: 8px 12px;
  background: transparent;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Noto Sans SC", sans-serif;
}
.starry-player {
  --st-text: currentColor;
  --t-main: var(--st-text);
  --t-dim: color-mix(in srgb, var(--st-text) 76%, transparent);
  --t-mute: color-mix(in srgb, var(--st-text) 48%, transparent);
  --t-line: color-mix(in srgb, var(--st-text) 26%, transparent);
  --tr: .4s cubic-bezier(.33, 1, .68, 1);
  position: relative;
  width: 100%;
  margin: 8px 0;
  border-top: none;
  border-bottom: none;
  padding: 0;
  color: var(--t-dim);
  background: none;
}
.player-head {
  list-style: none;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 34px;
  align-items: center;
  min-height: 38px;
  padding: 8px 18px;
  cursor: pointer;
  user-select: none;
  color: var(--t-dim);
  background: none;
  transition: color var(--tr);
}
.player-head::-webkit-details-marker { display: none; }
.player-balance { visibility: hidden; }
.player-title-box {
  grid-column: 2;
  justify-self: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.player-title-box::before,
.player-title-box::after {
  content: "";
  font-size: 13px;
  color: var(--t-dim);
  opacity: 0.8;
  animation: twinkle ease-in-out infinite;
  line-height: 1;
  background: none;
}
.player-title-box::before {
  content: "⊹ ࣪ ˖";
  animation-duration: 2.4s;
  animation-delay: 0.1s;
  margin-right: 2px;
}
.player-title-box::after {
  content: "˖ ࣪ ⊹";
  animation-duration: 2.2s;
  animation-delay: 0.7s;
  margin-left: 2px;
}
.player-title {
  display: inline-flex;
  font-family: inherit;
  font-size: 13px;
  font-weight: 400;
  letter-spacing: 0.12em;
  line-height: 1.18;
  white-space: nowrap;
  color: var(--t-dim);
}
.player-arrow {
  grid-column: 3;
  justify-self: center;
  width: 8px;
  height: 8px;
  border-right: 1.5px solid var(--t-mute);
  border-bottom: 1.5px solid var(--t-mute);
  transform: translateY(-2px) rotate(45deg);
  opacity: 0.64;
  transition: transform 0.22s ease, opacity 0.22s ease;
}
.starry-player[open] .player-arrow {
  transform: translateY(2px) rotate(225deg);
  opacity: 0.9;
  border-color: var(--t-main);
}
.player-body {
  position: relative;
  z-index: 1;
  padding: 0 13px 14px 13px;
  opacity: 0;
  transform: translateY(6px);
  animation: choiceFlyIn 0.35s forwards;
}
.stardust-line {
  text-align: center;
  font-size: 14px;
  color: var(--t-mute);
  margin: 0 0 10px 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.stardust-line span {
  display: inline-block;
  animation: twinkleSoft ease-in-out infinite;
}
.stardust-line .dust-left { animation-duration: 2.1s; animation-delay: 0s; }
.stardust-line .dust-core { animation-duration: 2.8s; animation-delay: 0.45s; font-size: 1.1em; }
.stardust-line .dust-right { animation-duration: 2.4s; animation-delay: 0.9s; }
.poem-casket {
  position: relative;
  margin-bottom: 12px;
  padding: 8px 12px;
  border-radius: 20px;
  background: color-mix(in srgb, var(--t-main) 5%, transparent);
  border: 1px solid var(--t-line);
  transition: border 0.2s ease;
}
.poem-casket:hover { border-color: var(--t-mute); }
.poem-text {
  font-family: "STSong", "Songti SC", "Noto Serif SC", serif;
  font-size: 12px;
  line-height: 1.55;
  text-align: center;
  letter-spacing: 0.04em;
  color: var(--t-dim);
  white-space: pre-wrap;
}
.music-vessel {
  position: relative;
  border-radius: 24px;
  border: 1px solid var(--t-line);
  padding: 12px 12px 10px;
  background: color-mix(in srgb, var(--t-main) 4%, transparent);
  transition: border-color 0.2s;
}
.music-vessel:hover { border-color: var(--t-mute); }
.disc-row {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr) 44px;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}
.vinyl-star {
  position: relative;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,240,0.2), color-mix(in srgb, var(--t-main) 12%, transparent) 70%);
  box-shadow: 0 0 0 1px var(--t-line), 0 0 0 3px color-mix(in srgb, var(--t-main) 6%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
}
.vinyl-star.spinning { animation: vinylSpin 5s linear infinite; }
.cover-mini {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  overflow: hidden;
  background: color-mix(in srgb, var(--t-main) 8%, transparent);
  border: 1px solid var(--t-line);
  display: flex;
  align-items: center;
  justify-content: center;
}
.cover-mini img { width: 100%; height: 100%; object-fit: cover; }
.cover-mini .no-cover { font-size: 12px; color: var(--t-mute); }
.song-aura { min-width: 0; }
.song-label {
  font-size: 9px;
  letter-spacing: 0.2em;
  color: var(--t-mute);
  margin-bottom: 4px;
  text-transform: uppercase;
}
.song-title {
  font-size: 14px;
  font-weight: 500;
  color: var(--t-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.song-artist {
  font-size: 11px;
  color: var(--t-mute);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-top: 2px;
}
.equalizer {
  display: flex;
  align-items: end;
  gap: 3px;
  height: 16px;
  margin-top: 5px;
  opacity: 0.5;
}
.equalizer i {
  display: block;
  width: 2.5px;
  background: var(--t-dim);
  border-radius: 2px;
}
.starry-player.is-playing .equalizer { opacity: 0.9; }
.starry-player.is-playing .equalizer i { animation: equalizeWave 0.65s ease-in-out infinite; }
.starry-player.is-playing .equalizer i:nth-child(2) { animation-duration: 0.55s; animation-delay: -0.15s; }
.starry-player.is-playing .equalizer i:nth-child(3) { animation-duration: 0.7s; animation-delay: -0.3s; }
.starry-player.is-playing .equalizer i:nth-child(4) { animation-duration: 0.5s; animation-delay: -0.1s; }
.starry-player.is-playing .equalizer i:nth-child(5) { animation-duration: 0.8s; animation-delay: -0.25s; }
.play-star-btn {
  justify-self: center;
  width: 42px;
  height: 42px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--t-main) 6%, transparent);
  border: 1px solid var(--t-line);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--t-mute);
  transition: all 0.2s ease;
}
.play-star-btn:hover {
  transform: scale(1.05);
  border-color: var(--t-main);
  color: var(--t-main);
}
.play-star-btn svg { width: 18px; height: 18px; fill: currentColor; }
.control-bar {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) 36px;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  margin-bottom: 6px;
}
.time-stamp {
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  color: var(--t-mute);
  text-align: center;
}
.slider-starry {
  width: 100%;
  height: 16px;
  background: transparent;
  -webkit-appearance: none;
  appearance: none;
  cursor: pointer;
}
.slider-starry::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--t-main) 30%, transparent);
}
.slider-starry::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 12px;
  height: 12px;
  margin-top: -4px;
  border-radius: 50%;
  background: var(--t-main);
  border: 1px solid color-mix(in srgb, var(--t-main) 40%, white);
  box-shadow: 0 0 5px var(--t-main);
  cursor: pointer;
}
.slider-starry::-webkit-slider-thumb:hover { transform: scale(1.15); }
.js-progress {
  background: linear-gradient(90deg, var(--t-main) 0%, var(--t-main) var(--progress-percent,0%), color-mix(in srgb, var(--t-main) 25%, transparent) var(--progress-percent,0%));
  background-repeat: no-repeat;
}
.volume-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 8px;
  padding-top: 4px;
}
.volume-icon {
  font-size: 11px;
  letter-spacing: 1px;
  color: var(--t-mute);
  min-width: 28px;
}
.volume-slider { flex: 1; }
.volume-slider::-webkit-slider-runnable-track { background: color-mix(in srgb, var(--t-main) 40%, transparent); height: 4px; }
.status-badge {
  background: color-mix(in srgb, var(--t-main) 5%, transparent);
  border-radius: 40px;
  padding: 2px 8px;
  font-size: 9px;
  color: var(--t-mute);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 105px;
  text-align: center;
  border: 0.5px solid var(--t-line);
}
.hidden-data { display: none !important; }
@media (max-width: 600px) {
  body { padding: 4px 8px; }
  .player-head { min-height: 36px; padding: 7px 13px; grid-template-columns: 28px minmax(0,1fr) 28px; }
  .player-title { font-size: 12px; }
  .disc-row { grid-template-columns: 48px minmax(0,1fr) 38px; gap: 8px; }
  .vinyl-star { width: 48px; height: 48px; }
  .cover-mini { width: 38px; height: 38px; }
  .play-star-btn { width: 36px; height: 36px; }
  .play-star-btn svg { width: 16px; height: 16px; }
  .song-title { font-size: 13px; }
  .slider-starry { height: 14px; }
}
</style>
