    };

    const DEFAULT_MODEL_CONFIG = {
      gemini: ["🔒丨Core", "✨丨Gemini", "✨丨通用", "✨丨思考模式（繁）"],
      glm: ["✴️丨GLM Core", "✴️丨思考模式", "✨丨通用"],
      claude: ["🔒丨Core", "🎨丨思考模式", "🎨丨Claude专用", "🎨丨克系列"],
      c45s: ["🔒丨Core", "🎨丨思考模式", "🎨丨克系列", "✨丨Gemini"],
