      if (edit) btn.setAttribute("data-edit", "true");
      btn.innerHTML = `<div class="menu-item-text">${text}</div>${group ? `<span class="binding-badges"><span class="binding-badge mutex" title="互斥组：${group}"></span></span>` : ""}<div class="toggle-led"></div>`;
