                 targetGroupForAdd.insertBefore(container, targetGroupForAdd.firstChild);
               }
               container.appendChild(newBtn);
            }
            root.classList.remove("search-active");
            searchInput.value = "";
          });
          searchResults.appendChild(div);
        }
      });
