      if (btn.classList.contains("del")) {
         if (btn.closest(".edit-tools-main")) {
           if (confirm("确定要恢复默认UI吗？这会刷新整个悬浮窗。")) {
             localStorage.removeItem(getCurrentUiCacheKey());
             localStorage.removeItem("orbV7_custom_ui");
             Object.keys(localStorage).forEach((key) => {
               if (/^orbV\d+(?:\.\d+)*_custom_ui$/.test(key)) localStorage.removeItem(key);
             });
             localStorage.removeItem("orbV7_model_config");
             localStorage.removeItem("orbV7_model_meta");
             localStorage.removeItem("orbV7_model_rec_config");
             localStorage.removeItem("orbV7_regex_bindings");
             localStorage.removeItem("orbV7_script_bindings");
